/**
 * diff 解析器，对齐 parse-diff@0.11.1 的能力
 * 支持解析 git diff / git patch / svn diff / hg diff / GNU diff / GitHub API patch 等格式
 */
export interface NormalChange {
    type: 'normal';
    normal: true;
    ln1: number;
    ln2: number;
    content: string;
}
export interface AddChange {
    type: 'add';
    add: true;
    ln: number;
    content: string;
}
export interface DeleteChange {
    type: 'del';
    del: true;
    ln: number;
    content: string;
}
export type ChangeType = 'normal' | 'add' | 'del';
export type Change = NormalChange | AddChange | DeleteChange;
export interface Chunk {
    content: string;
    changes: Change[];
    oldStart: number;
    oldLines: number;
    newStart: number;
    newLines: number;
}
export interface File {
    chunks: Chunk[];
    deletions: number;
    additions: number;
    from?: string;
    to?: string;
    oldMode?: string;
    newMode?: string;
    index?: string[];
    deleted?: true;
    new?: true;
}
export type DiffChange = Change;
export type DiffChunk = Chunk;
export type DiffFile = File;
export declare function parseDiff(input: string | null | undefined): File[];
